/* Inventory quantities are serving portions. All clocks use simulated seconds. */
(()=>{
const groups={coffee:['Original Blend','Cold Brew','Decaf'],milk:['Almond','Oat Milk','Whole Milk','Cream','Sweet Cream'],syrup:['Vanilla','Caramel','Mocha','Pumpkin Spice','Brown Sugar'],topping:['Whipped Cream','Cinnamon','Chocolate Drizzle','Cold Foam','Caramel Drizzle'],bakery:['Croissant','Breakfast Sandwich','Cookie'],supplies:['Cup','Lid','Straw','Utensil','Bakery Bag','Napkin']};
// Each product has one assigned company. No supplier comparison wall or mixed-company cart.
const companies={
 'Original Blend':['Rise Roasters','☕','#865a36',35], 'Cold Brew':['Chill Coffee Co.','❄','#327d8e',30], Decaf:['Gentle Bean','☕','#947249',35],
 Almond:['Almond Grove','✿','#987447',25], 'Oat Milk':['Oatfield','🌾','#a77d36',25], 'Whole Milk':['Meadow Dairy','🥛','#477c64',25], Cream:['Creamery Lane','🥛','#568c80',25], 'Sweet Cream':['Sweet Meadow','🥛','#a46b79',25],
 Vanilla:['Vanilla House','✿','#94732e',35], Caramel:['Golden Kettle','◆','#b67b2d',35], Mocha:['Cocoa Works','◆','#7a503a',35], 'Pumpkin Spice':['Harvest Spice','✿','#b76535',35], 'Brown Sugar':['Amber Pantry','◆','#94703a',35],
 'Whipped Cream':['Cloud Creamery','☁','#7c8ba7',25], Cinnamon:['Cinnamon Grove','✿','#a6603c',35], 'Chocolate Drizzle':['Cocoa Ribbon','◆','#795240',35], 'Cold Foam':['Foam & Co.','☁','#5d8b94',25], 'Caramel Drizzle':['Caramel Ribbon','◆','#b08536',35],
 Croissant:['Butter Fold','🥐','#aa7b42',20], 'Breakfast Sandwich':['Morning Kitchen','🥪','#75854b',20], Cookie:['Cookie Corner','🍪','#ac764b',20],
 Cup:['CupCraft','☕','#547d64',20], Lid:['SnapSeal','◎','#507f94',20], Straw:['Sip & Stem','╱','#7a9461',20], Utensil:['TableKind','🍴','#7a7f9b',20], 'Bakery Bag':['Paper Parcel','▣','#a78455',20], Napkin:['SoftFold','▧','#8c829f',20]
};
const items=Object.entries(groups).flatMap(([group,names])=>names.map((name,i)=>({name,group,cost:group==='bakery'?[.85,1.5,.55][i]:group==='coffee'?.4:group==='milk'?.3:group==='supplies'?[.15,.06,.04,.08,.1,.03][i]:.18,cap:group==='bakery'?16:group==='supplies'?40:24,life:group==='bakery'?320:group==='milk'||['Whipped Cream','Cold Foam'].includes(name)?610:1800,company:companies[name][0],icon:companies[name][1],color:companies[name][2],lead:companies[name][3]})));
const names=['Maya','Lily','Sophie','Ava','Zoe','Noah','Leo','Amir','Ethan','Miles'];
class InventorySim{
 constructor(){this.clock=0;this.daypart=0;this.cash=110;this.running=false;this.ended=false;this.reports=[];this.deliveries=[];this.lots={};this.orders=[];this.messages=[];this.serial=0;this.deliveryCount=0;this.history=[];this.nextSample=0;this.totalWaste=0;items.forEach(x=>{const n=x.name==='Oat Milk'?2:x.group==='bakery'?3:x.group==='supplies'?16:6;this.add(x.name,n,x.cost,x.life);});this.begin();}
 begin(){this.elapsed=0;this.nextArrival=0;this.orders=[];this.ended=false;this.running=false;this.metrics={arrived:0,served:0,lost:0,revenue:0,cogs:0,waste:0,wasteUnits:0,fees:0,purchases:0,wait:0,supplyWait:0,satisfaction:0,lostSales:0,demand:{},stockouts:0};this.schedule=this.daypart===0?[0,35,70,105,130,155,180,205]:this.daypart===1?[0,25,50,75,95,115,135,155,185,220]:[0,45,90,135,180,225];this.notice(['Morning challenge: oat milk is running low. Plan ahead!','Afternoon: cold brew and oat milk are popular. Watch delivery lead times.','Evening: demand is quieter. Avoid buying more than you can sell.'][this.daypart]);this.sample();}
 get label(){return ['Morning','Afternoon','Evening'][this.daypart];}
 stock(name){return (this.lots[name]||[]).reduce((a,b)=>a+b.qty,0);}
 add(name,qty,cost,life){if(qty>0)(this.lots[name]??=[]).push({qty,cost,expires:this.clock+life});}
 notice(text){this.messages.unshift(text);this.messages=this.messages.slice(0,6);}
 recipe(i){const p=this.daypart;return {coffee:p===1?(i%3?'Cold Brew':'Decaf'):(i%4===3?'Decaf':'Original Blend'),milk:i%3===0?'Oat Milk':i%3===1?'Whole Milk':'Almond',syrup:groups.syrup[(i+p)%5],topping:groups.topping[(i+p)%5],bakery:i%3===1?null:groups.bakery[(i+p)%3]};}
 needed(recipe){return ['Cup','Lid','Napkin',...(recipe.coffee==='Cold Brew'?['Straw']:[]),recipe.coffee,recipe.milk,recipe.syrup,recipe.topping,...(recipe.bakery?[recipe.bakery,'Bakery Bag',...(recipe.bakery==='Breakfast Sandwich'?['Utensil']:[])]:[])];}
 missing(o){return this.needed(o.recipe).filter(n=>this.stock(n)<1);}
 consume(name,n=1){let cost=0;const lots=this.lots[name].sort((a,b)=>a.expires-b.expires);for(const lot of lots){const take=Math.min(n,lot.qty);lot.qty-=take;n-=take;cost+=take*lot.cost;if(!n)break;}this.lots[name]=lots.filter(l=>l.qty>0);return cost;}
 forecast(){const d={};this.schedule.forEach((_,i)=>this.needed(this.recipe(i)).forEach(n=>d[n]=(d[n]||0)+1));return d;}
 suggested(name){const left=this.schedule.slice(this.nextArrival).reduce((n,_,j)=>n+this.needed(this.recipe(j+this.nextArrival)).filter(k=>k===name).length,0)+this.orders.filter(o=>o.status==='waiting'&&this.needed(o.recipe).includes(name)).length;const incoming=this.deliveries.filter(d=>!d.received).reduce((n,d)=>n+(d.cart[name]||0),0);return Math.max(0,left+(left>0?1:0)-this.stock(name)-incoming);}
 quote(cart,supplier){return Object.entries(cart).reduce((sum,[n,q])=>sum+items.find(x=>x.name===n).cost*q*(supplier==='express'?1.5:1),supplier==='express'?3:supplier==='wholesale'?1:.25);}
 purchase(cart,supplier){if(this.ended)return 'This shift is finished.';const entries=Object.entries(cart);if(!entries.length)return 'Choose at least one item.';if(entries.some(([n,q])=>!items.some(x=>x.name===n)||!Number.isInteger(q)||q<1))return 'Choose whole quantities greater than zero.';const product=items.find(x=>x.company===supplier);if(!['express','wholesale'].includes(supplier)&&(!product||entries.some(([name])=>name!==product.name)))return 'Order this product from its assigned company.';if(supplier==='wholesale'&&entries.reduce((s,[,q])=>s+q,0)<5)return 'Wholesaler minimum: 5 portions total.';if(entries.some(([n,q])=>this.stock(n)+q+this.deliveries.filter(d=>!d.received).reduce((s,d)=>s+(d.cart[n]||0),0)>items.find(x=>x.name===n).cap))return 'Not enough shelf space. Try a smaller order.';const lead=product?product.lead:supplier==='express'?15:55;if(this.elapsed+lead>=300)return 'This delivery would arrive after closing.';const cost=this.quote(cart,supplier);if(cost>this.cash)return 'Not enough cash. Try a smaller order.';this.cash-=cost;this.metrics.purchases+=cost;this.metrics.fees+=product?.25:supplier==='express'?3:1;this.deliveries.push({id:++this.deliveryCount,cart:{...cart},supplier,cost,eta:this.clock+lead,lead,received:false});this.notice(`${supplier} ordered. Delivery in ${lead} seconds.`);return null;}
 receive(id){const d=this.deliveries.find(x=>x.id===id);if(!d||d.received||this.clock<d.eta)return false;let short=null;for(const [n,q]of Object.entries(d.cart)){const x=items.find(x=>x.name===n);const shortage=d.supplier==='wholesale'&&d.id%3===0&&!short&&q>1?1:0;if(shortage){short=n;const refund=x.cost;this.cash+=refund;this.metrics.purchases-=refund;}this.add(n,q-shortage,x.cost*(d.supplier==='express'?1.5:1),x.life);}d.received=true;this.notice(short?`Delivery checked: 1 ${short} missing. Refunded automatically. Reorder if needed.`:'Delivery checked and shelved. Your stock is ready!');return true;}
 sample(){this.history.push({t:this.clock,shift:this.daypart,stock:Object.fromEntries(items.map(x=>[x.name,this.stock(x.name)])),queue:this.orders.filter(o=>o.status==='waiting').length});this.nextSample=this.clock+5;}
 tick(dt){if(!this.running||this.ended)return;dt=Math.min(dt,1);this.clock+=dt;this.elapsed+=dt;
 for(const x of items){this.lots[x.name]=this.lots[x.name].filter(l=>{if(l.expires>this.clock)return true;this.metrics.waste+=l.qty*l.cost;this.metrics.wasteUnits+=l.qty;this.totalWaste+=l.qty;return false;});}
 while(this.nextArrival<this.schedule.length&&this.elapsed>=this.schedule[this.nextArrival]){const i=this.nextArrival++;const recipe=this.recipe(i);const o={id:++this.serial,index:(i+this.daypart*3)%10,name:names[(i+this.daypart*3)%10],recipe,arrival:this.clock,status:'waiting',supplyWait:0,price:6+(recipe.bakery?3:0),warned:false};this.orders.push(o);this.metrics.arrived++;this.needed(recipe).forEach(n=>this.metrics.demand[n]=(this.metrics.demand[n]||0)+1);}
 for(const o of this.orders){if(o.status!=='waiting')continue;if(this.missing(o).length){o.supplyWait+=dt;this.metrics.supplyWait+=dt;if(!o.warned){o.warned=true;this.metrics.stockouts++;this.notice(`${o.name} needs ${this.missing(o).join(', ')}. Order supplies to unblock the line.`);}}if(this.clock-o.arrival>=100){o.status='lost';this.metrics.lost++;this.metrics.lostSales+=o.price;this.notice(`${o.name} left after waiting too long. Potential sale lost: $${o.price}.`);}}
 const active=this.orders.find(o=>o.status==='preparing');if(active&&this.clock>=active.ready){active.status='served';active.finished=this.clock;const wait=this.clock-active.arrival;active.satisfaction=Math.max(20,100-Math.max(0,wait-20)*.8);this.cash+=active.price;Object.assign(this.metrics,{served:this.metrics.served+1,revenue:this.metrics.revenue+active.price,wait:this.metrics.wait+wait,satisfaction:this.metrics.satisfaction+active.satisfaction});this.notice(`${active.name} served! +$${active.price}. Wait: ${Math.round(wait)} seconds.`);}
 if(!this.orders.some(o=>o.status==='preparing')){const o=this.orders.find(o=>o.status==='waiting'&&!this.missing(o).length);if(o){o.status='preparing';o.ready=this.clock+12+(o.recipe.bakery?6:0);this.needed(o.recipe).forEach(n=>this.metrics.cogs+=this.consume(n));}}
 if(this.clock>=this.nextSample)this.sample();if(this.elapsed>=300)this.finish();}
 finish(){if(this.ended)return;this.orders.filter(o=>['waiting','preparing'].includes(o.status)).forEach(o=>{o.status='lost';this.metrics.lost++;this.metrics.lostSales+=o.price;});this.running=false;this.ended=true;this.elapsed=300;const m=this.metrics;this.reports.push({...m,daypart:this.daypart,label:this.label,profit:m.revenue-m.cogs-m.waste-m.fees,averageWait:m.served?m.wait/m.served:0,averageSatisfaction:m.served?m.satisfaction/m.served:0,cash:this.cash});this.sample();}
 next(){if(!this.ended||this.daypart===2)return;this.daypart++;this.begin();}
}
window.InventorySim=InventorySim;window.INVENTORY_ITEMS=items;window.INVENTORY_GROUPS=groups;
})();
